// th15_s4_b4  TH15 v1.00b Stage 4 BossCard2「玉符「穢身探知型機雷」」
// 源：st04bs.ecl.txt:1402-1468 BossCard2（入口）/ 1470-1518 BossCard2_at、at2 /
//     542-643 BCirC02 子敌与其开火 BCirC02_at
// 外壳：独立无敌 control 敌承载段；子敌按批准的无敌存活路径，死亡回调 BCirC02Dead 不触发。

const TH15_RICE: int = 480;      // 源 type 8
const TH15_TALISMAN: int = 528;  // 源 type 11

const TIME_LIMIT: int = 3124;    // 120 开场 + 3000 源时限 + 4 入口清理
const OPENING_BUFFER: int = 120;

const MINE_COLOR: int = 6;       // 源 BossCard2_at: $I1 = 6，子敌继承后作为 etSprite 颜色

// 源 BCirC02_at 第二组 EX：ANIM（出生表现，按批准省略）→ WAIT 300 → DIFF>1 时
// VELTIME 60 帧把标量速 0.001 提到 0.4
xformdef RICE_RAMP {
    @300 add_speed(0fx);
    step_speed(0.4fx, 60 + 65536 * EASE_LINEAR);
}

// 源 BCirC02_at（608-643）：etAim 3 的固定方向整周环，3 路 × 1 层，颜色继承 $I1。
// 两组都带 ANIM(a=1) 出生退位移 4×初速，按批准口径保留。
sub mine_burst(color: int) {
    // 第一组 etAngle 用 %RANDRAD；整组开火只抽一次（Easy 在 NHL 门之前也已读取）
    var base: angle = (rand(65536) - 32768) as angle;
    if global(GVAR_RANK) >= 1 {
        // 第一组：TALISMAN，初速 1.0，退位移 4px。源再挂 VELTIME r=1.0，与初速相同，无数值变化。
        for i in 0..3 {
            var a1: angle = base + (((i * 65536) / 3) as angle);
            _ = fire(TH15_TALISMAN, color,
                     $self_x - 4fx * cos(a1), $self_y - 4fx * sin(a1),
                     1fx, a1, none, none);
        }
    }
    // 第二组：RICE，初速 0.001（退位移约 0.004px），基准角取本帧运动方向（源 %FINAL_ANGLE）
    var dir: angle = $self_angle;
    for j in 0..3 {
        var a2: angle = dir + (((j * 65536) / 3) as angle);
        var x2: fx = $self_x - 0.004fx * cos(a2);
        var y2: fx = $self_y - 0.004fx * sin(a2);
        if global(GVAR_RANK) >= 2 {
            _ = fire(TH15_RICE, color, x2, y2, 0.001fx, a2, RICE_RAMP, none);
        } else {
            _ = fire(TH15_RICE, color, x2, y2, 0.001fx, a2, none, none);
        }
    }
}

// 源 BCirC02（542-579）：受击框 24×24→12、体碰框 16×16→8；
// 出生 flagSet(15) 含 0x2 禁体碰，60 帧后 flagClear(3) 开体碰；之后每帧 1.0 速度漂移，
// 出生 310 帧后开火一次，随即 delete()。
async sub mine(color: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_vel(0, aim_player(), 0.2fx, EASE_LINEAR);  // moveVel(%ANGLE_PLAYER, 0.2)
    wait(60);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    move_speed(0, 1fx, EASE_LINEAR);                // moveSpeed(1.0)
    wait(250);
    mine_burst(color);
    // 源 delete()：主任务返回即静默退场
}

// 源 BossCard2_at（1470-1501）：在 (0,300) 为心、半径 160 的圆上生成子敌；
// 圆心角每步 Easy 20°、其余 10°，间隔 Easy 20 帧、其余 10 帧；$D=13000 远超卡窗口。
sub at_stream() {
    var c: angle = -90deg;                           // %C = -1.570796f
    for i in 0..13000 {
        var x: fx = 160fx * cos(c);                  // circlePos(%A, %B, %C, 160)
        var y: fx = 160fx * sin(c) + 300fx;          // %B += 300
        if global(GVAR_RANK) == 0 { c = c - 20deg; } else { c = c - 10deg; }
        _ = spawn_enemy(x, y, 300, 0, 1000, 0, mine(MINE_COLOR));
        if global(GVAR_RANK) == 0 { wait(20); } else { wait(10); }
    }
}

// 源 BossCard2_at2（1503-1518）：13 只自 y=-32、x=192→-192 每 10 帧一只，颜色 $I1=4。
// 源在同步 at() 返回后才调用它；at() 内约 130000 帧，故窗口内不执行，保留实现不删源结构。
sub at2_row() {
    var x: fx = 192fx;
    for i in 0..13 {
        _ = spawn_enemy(x, -32fx, 300, 0, 1000, 0, mine(4));
        x = x - 32fx;
        wait(10);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // 源入口 4 帧清理（章节/统计/符声明/清场，无新增攻击），随后 timerReset
    wait(4);
    wait(90);   // timerReset 后到 +90 标签，首只子敌在源脚本 gate 94
    for round in 0..1000 {   // 源 BossCard2_1352 外层 $D = 1000
        at_stream();
        wait(120);
        at2_row();
        wait(120);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 46, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
